import{c as d,Q as e,j as a,m as o}from"./chunks/framework.DjobWxAB.js";const b=JSON.parse('{"title":"RBQ API 개요","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/API.md","filePath":"ko/software/API.md","lastUpdated":1779182288000}'),r={name:"ko/software/API.md"};function i(c,t,n,h,s,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="rbq-api-개요" tabindex="-1">RBQ API 개요 <a class="header-anchor" href="#rbq-api-개요" aria-label="Permalink to &quot;RBQ API 개요&quot;">​</a></h1><p><strong>RBQ API</strong>는 개발자가 RBQ 사족보행 로봇을 제어하고 상호작용할 수 있는 포괄적인 C++ 인터페이스를 제공합니다. 멀티프로세스 환경에서 저수준 실시간 제어와 고수준 행동 명령을 모두 지원하도록 설계되었습니다.</p><h2 id="프로세스-id-모션-소유권" tabindex="-1">프로세스 ID (모션 소유권) <a class="header-anchor" href="#프로세스-id-모션-소유권" aria-label="Permalink to &quot;프로세스 ID (모션 소유권)&quot;">​</a></h2><p><code>RBQ_API</code> 인스턴스를 생성할 때 <strong>프로세스 ID</strong>를 제공해야 합니다:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RBQ_API</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 사용자 애플리케이션용 프로세스 ID (20-39 범위)</span></span></code></pre></div><p>이 ID는 <strong>모션 소유권 메커니즘</strong>을 사용하여 안전한 멀티프로세스 제어를 보장하며, 각 관절은 소유자 프로세스에 의해서만 제어될 수 있습니다.</p><blockquote><p>⚠️ 관절 명령을 보내기 전에 항상 setMotionOwner()를 호출하세요.</p></blockquote><hr><h2 id="api-구조-요약" tabindex="-1">API 구조 요약 <a class="header-anchor" href="#api-구조-요약" aria-label="Permalink to &quot;API 구조 요약&quot;">​</a></h2><table tabindex="0"><thead><tr><th>카테고리</th><th>구성요소</th><th>설명</th></tr></thead><tbody><tr><td><strong>제어</strong></td><td><code>Joint</code></td><td>저수준 관절 제어: 위치, 토크, 게인 (Kp/Kd)</td></tr><tr><td></td><td><code>startMoveJoint()</code> / <code>stopMoveJoint()</code></td><td>관절별 조그 모션 시작/중지</td></tr><tr><td></td><td><code>lockUnlockJoint()</code></td><td>수동 조작을 위한 관절 잠금/해제</td></tr><tr><td><strong>센서</strong></td><td><code>IMU</code></td><td>자세 (쿼터니언/RPY), 자이로, 가속도 접근</td></tr><tr><td></td><td><code>getBatteryVoltage()</code></td><td>배터리 전압 읽기 (내부 전용)</td></tr><tr><td><strong>게임패드</strong></td><td><code>Gamepad</code></td><td>Logitech F710 게임패드 입력 접근: 조그, 트리거, 버튼</td></tr><tr><td><strong>고수준 모션</strong></td><td><code>motionStaticReady()</code> / <code>motionDynamicWalk()</code> 등</td><td>미리 정의된 로봇 행동</td></tr></tbody></table><hr><h2 id="관절-제어-api-rbq-api-joint" tabindex="-1">관절 제어 API (<code>RBQ_API::Joint</code>) <a class="header-anchor" href="#관절-제어-api-rbq-api-joint" aria-label="Permalink to &quot;관절 제어 API (`RBQ_API::Joint`)&quot;">​</a></h2><h3 id="센서-값-읽기" tabindex="-1">센서 값 읽기 <a class="header-anchor" href="#센서-값-읽기" aria-label="Permalink to &quot;센서 값 읽기&quot;">​</a></h3><table tabindex="0"><thead><tr><th>함수</th><th>설명</th></tr></thead><tbody><tr><td><code>getPos()</code></td><td>관절 위치 읽기 (rad)</td></tr><tr><td><code>getVel()</code></td><td>관절 속도 읽기 (rad/s)</td></tr><tr><td><code>getTorque()</code></td><td>관절 토크 읽기 (Nm)</td></tr><tr><td><code>getGainKp()</code> / <code>getGainKd()</code></td><td>현재 Kp/Kd 게인 읽기</td></tr></tbody></table><h3 id="명령-전송" tabindex="-1">명령 전송 <a class="header-anchor" href="#명령-전송" aria-label="Permalink to &quot;명령 전송&quot;">​</a></h3><table tabindex="0"><thead><tr><th>함수</th><th>설명</th></tr></thead><tbody><tr><td><code>setMotionOwner()</code></td><td>관절 제어권 획득</td></tr><tr><td><code>setPosRef()</code></td><td>관절 위치 목표 설정</td></tr><tr><td><code>setTorqueRef()</code></td><td>토크 목표 설정 (Nm)</td></tr><tr><td><code>setGainKp()</code> / <code>setGainKd()</code></td><td>양자화를 통한 제어 게인 설정</td></tr></tbody></table><blockquote><p>✅ 각 관절은 제어 명령을 받기 위해 소유자 프로세스가 있어야 합니다.</p></blockquote><hr><h2 id="imu-센서-api-rbq-api-imu" tabindex="-1">IMU 센서 API (<code>RBQ_API::IMU</code>) <a class="header-anchor" href="#imu-센서-api-rbq-api-imu" aria-label="Permalink to &quot;IMU 센서 API (`RBQ_API::IMU`)&quot;">​</a></h2><p>로봇의 자세와 운동 상태에 대한 접근을 제공합니다.</p><table tabindex="0"><thead><tr><th>함수</th><th>출력</th></tr></thead><tbody><tr><td><code>getQuaternion()</code></td><td>Eigen 쿼터니언으로 자세 (w, x, y, z)</td></tr><tr><td><code>getRPY()</code></td><td>롤, 피치, 요 (ZYX 오일러 각도, 라디안)</td></tr><tr><td><code>getGyro()</code></td><td>각속도 (rad/s) (X, Y, Z)</td></tr><tr><td><code>getAcc()</code></td><td>선형 가속도 (m/s²) (X, Y, Z)</td></tr></tbody></table><hr><h2 id="게임패드-api-rbq-api-gamepad" tabindex="-1">게임패드 API (<code>RBQ_API::Gamepad</code>) <a class="header-anchor" href="#게임패드-api-rbq-api-gamepad" aria-label="Permalink to &quot;게임패드 API (`RBQ_API::Gamepad`)&quot;">​</a></h2><p>원격 조작을 위한 <strong>Logitech F710 (X 모드)</strong> 지원.</p><table tabindex="0"><thead><tr><th>타입</th><th>함수</th><th>설명</th></tr></thead><tbody><tr><td>조이스틱</td><td><code>getLeftJogX/Y()</code>, <code>getRightJogX/Y()</code></td><td>범위: [-1.0, 1.0]</td></tr><tr><td>트리거</td><td><code>getLeftTrigger()</code>, <code>getRightTrigger()</code></td><td>범위: [0.0, 1.0]</td></tr><tr><td>버튼</td><td><code>getButtonState(Button::X)</code></td><td>눌렸을 때 <code>true</code> 반환</td></tr></tbody></table><hr><h2 id="내장-모션-프로그램" tabindex="-1">내장 모션 프로그램 <a class="header-anchor" href="#내장-모션-프로그램" aria-label="Permalink to &quot;내장 모션 프로그램&quot;">​</a></h2><p>미리 정의된 로봇 행동을 쉽게 트리거할 수 있습니다:</p><table tabindex="0"><thead><tr><th>함수</th><th>설명</th></tr></thead><tbody><tr><td><code>motionStaticReady()</code></td><td>준비 자세로 이동</td></tr><tr><td><code>motionStaticGround()</code></td><td>바닥에 눕는 자세</td></tr><tr><td><code>motionDynamicWalk()</code></td><td>동적 보행 시작</td></tr><tr><td><code>motionDynamicRun()</code></td><td>동적 달리기 시작</td></tr><tr><td><code>motionDynamicAim()</code></td><td>조작/비전을 위한 조준 자세</td></tr><tr><td><code>motionDynamicStairs()</code></td><td>계단 오르기 모션</td></tr><tr><td><code>motionDynamicHealthCheck()</code></td><td>진단 모션</td></tr></tbody></table><hr>',30)])])}const g=d(r,[["render",i]]);export{b as __pageData,g as default};
